# pacman.map — logical name -> real Arch package(s).
# Only rows where the name differs (§1); unlisted names pass through unchanged.

build = base-devel
dev-headers = openssl pkgconf
gh = github-cli
i3 = i3-wm

# --- AUR method rows (§4) — hyprland-glass rice, Arch-only ---------------------
# paru is the chicken/egg helper: built from source (source:provide_paru); list it
# before any aur: package in the manifest (order is the dependency graph, §4).
# Everything below installs via the detected helper (paru/yay) as OSR_USER; the
# logical name maps to the real AUR package where they differ (e.g. *-bin).
paru = source:provide_paru

# DE / desktop AUR packages
wleave = aur:wleave
wlogout = aur:wlogout
luminance = aur:luminance
bibata-cursor-theme = aur:bibata-cursor-theme-bin
xf86-video-vmware = aur:xf86-video-vmware-git
captdriver = aur:captdriver-git
mda-lv2 = aur:mda-lv2-git
libdeep-filter-ladspa = aur:libdeep_filter_ladspa-bin
waydroid-image-gapps = aur:waydroid-image-gapps

# Legacy NVIDIA driver branches (modules/gpu-drivers.sh). Each NVIDIA generation
# is frozen on the last branch that supported it, and every one of those lives in
# the AUR: 570xx = Maxwell/Pascal/Volta, 470xx = Kepler, 390xx = Fermi,
# 340xx = Tesla. Turing+ uses the repo nvidia-open-dkms and needs no row here.
# When NVIDIA drops another generation from the current branch, the fix is one
# new group of rows here plus one case arm in the module — nowhere else.
nvidia-570xx-dkms = aur:nvidia-570xx-dkms
nvidia-570xx-utils = aur:nvidia-570xx-utils
lib32-nvidia-570xx-utils = aur:lib32-nvidia-570xx-utils
nvidia-570xx-settings = aur:nvidia-570xx-settings
opencl-nvidia-570xx = aur:opencl-nvidia-570xx

nvidia-470xx-dkms = aur:nvidia-470xx-dkms
nvidia-470xx-utils = aur:nvidia-470xx-utils
lib32-nvidia-470xx-utils = aur:lib32-nvidia-470xx-utils
nvidia-470xx-settings = aur:nvidia-470xx-settings
opencl-nvidia-470xx = aur:opencl-nvidia-470xx

nvidia-390xx-dkms = aur:nvidia-390xx-dkms
nvidia-390xx-utils = aur:nvidia-390xx-utils
lib32-nvidia-390xx-utils = aur:lib32-nvidia-390xx-utils
nvidia-390xx-settings = aur:nvidia-390xx-settings
opencl-nvidia-390xx = aur:opencl-nvidia-390xx

nvidia-340xx-dkms = aur:nvidia-340xx-dkms
nvidia-340xx-utils = aur:nvidia-340xx-utils
lib32-nvidia-340xx-utils = aur:lib32-nvidia-340xx-utils
nvidia-340xx-settings = aur:nvidia-340xx-settings
opencl-nvidia-340xx = aur:opencl-nvidia-340xx

# Arch split mesa's OpenCL out and renamed it rusticl (2024) — the logical name
# the modules use stays stable, the row absorbs the rename.
opencl-mesa = opencl-rusticl-mesa

# Application AUR packages
amneziavpn = aur:amneziavpn-bin
onlyoffice = aur:onlyoffice-bin
vscode-insiders = aur:visual-studio-code-insiders-bin
yandex-browser = aur:yandex-browser
zen-browser = aur:zen-browser-bin
steam-aur = aur:steam

# --- i3/X11 desktop (rices/void-i3-rosemuted) ---------------------------------
# The i3 rice is validated on Void; these rows are name mapping only, so the same
# manifest resolves on Arch too. X client utils already carry Arch's `xorg-*`
# names as their logical names, so they need no rows here (§1: no identity rows).
gnome-disks = gnome-disk-utility
gtk-dark-theme = gnome-themes-extra gtk-engine-murrine
nerd-fonts-symbols = ttf-nerd-fonts-symbols
gsimplecal = aur:gsimplecal
android-file-transfer = aur:android-file-transfer
raw-thumbnailer = aur:raw-thumbnailer
xidlehook = aur:xidlehook
betterlockscreen = aur:betterlockscreen
autotiling = aur:autotiling

# --- i3 desktop, second pass (name mapping only, Void is the validated target)
# Arch calls the distro VS Code build `code` (the MS-branded one is the AUR
# `visual-studio-code-bin`; modules/vscode-insiders.sh is the Insiders channel).
vscode = code
keyd = aur:keyd
kbdd = aur:kbdd
libinput-gestures = aur:libinput-gestures
rofimoji = aur:rofimoji
ncpamixer = aur:ncpamixer
batsignal = aur:batsignal
poweralertd = aur:poweralertd
